            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Ayışığında oturuyorduk\nBileğinden öptüm seni\nSonra ayakta öptüm\nDudağından öptüm seni\nKapı aralığında öptüm\nSoluğundan öptüm seni\nBahçede çocuklar vardı\nÇocuğundan öptüm seni\nBaşka evlerde karşılaştık\nİliğinden öptüm seni\nEn sonunda caddelere çıkardım\nKaynağından öptüm seni.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "iki şey: aşk ve şiir\nmutsuzlukla beslenir biri\nbiri ona dönüşür.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Özgürlüğün geldiği gün,\no gün ölmek yasak!", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Ey alınyazısı uzmanı,\nSuretlerle doldurursun yazını.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Güzelsin sevgilim,\nAma çok yakından!..", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Sen eteklerinden erdemler sarkan\nKırmızı başlıklı pis kız,\nDağ - taş derdinde bahçe toprağı,\nKulplu platin, paçalı tavuk,\nGeldin değiştirdin bütün anılarımı.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Ölüyürum tanrım.\nBu da oldu işte.\n\nHer ölüm erken ölümdür\nBiliyorum tanrım.\n\nAma, ayrıca, aldığın şu hayat\nFena değildir..\n\nÜstü kalsın..", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Evliliğin aşkı kesin öldürdüğü kanısındayım... Kendi deneyim için söylüyorum: Aşk meşru bir şey olamaz. O da şiir gibi meşrulaşınca ölür. Aşk da, şiir de uzlaşıcı olunca ölür. Genel olarak sanat böyledir... Masallar da çobanın prensese kavuştuğu an bitmiyor mu.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Şiirde azalan verimler kanunu var. Dil bir açıdan işlendikçe o alanda elde edilen verimler bir noktadan sonra azalmaya başlıyor. Bu, bir bunalıma yol açıyor. Bunalımlar da yeni şiir alanları, yeni açılar bulunmasıyla sona erer hep.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Şiirde asıl olan hikâye etmek değil, kelimeler arasında kurulacak \"şiirsel yük\"tür.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Halk deyimlerinin havası şiirin kanat çırpmasına imkân vermeyecek kadar dar bir havadır.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Konuşmuyor, anlatmıyor diye hissetmiyor sanmayın. Kimisi içine atar çığlıklarını.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Şiir her şeyi anlatma özgürlüğüünü kullanmalıdır diyorum. Bireyci şair için de doğru bu, toplumcu şair için de.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Adresim oldun benim. Biliyorsun bunu değil mi? Alınyazım oldun. Korka korka çaldım kapını. Ne yapayım sevdim seni... Sensin artık ne varsa...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Akla gelen, başa gelir diyorlar ya, yalan! Öyle olsa, milyonlarca sen düşerdi başıma.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Kimse beni sevmiyor\" diye bağırdım... Annem: \"ben daha ölmedim\" dedi.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Küfür diyorum, bir saldırmama eylemidir.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Aşklar da bakım istiyor, öğrenemedin gitti...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Ben nerede bir çift göz gördümse tuttum onu güzelce sana tamamladım. Sen binlerce yaşayasın diye yaptım bunu. Bir bunun için yaptım...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Bir çeşmeye koşar gibi koşuyorum sana. Anlasana!", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Göz göze gelebilirseniz, ipi kopmuş bir uçurtma, hızla uzaklaşır bakışlarından.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Hep kazanırsın ey çözümsüzlük!", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Hiçbir şeyim yok akıp giden sokaktan başka, keşke yalnız bunun için sevseydim seni...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Kehanet adlı kısacık bir şiir buldum. Keşke yalnız bunun için sevseydim seni.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Daha nen olayım isterdin, onursuzunum senin!", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Kuşlar toplanmış göçüyorlar; keşke yalnız bunun için sevseydim seni...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Neden yorgunsun sorusuna cevap aramaktan ve bunu sormasınlar diye gülümsemekten yoruldum...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Niye mi koşarsın böyle ufka doğru. Pir Sultan mı ısmarladı seni, Kızılırmak'tan öte Sivas'a doğru.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Önce sevdiğiniz terk eder sizi, arkasından uykunuz.. Sonra ne sevdiğiniz gelir geri, ne de uykunuz....", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Öyle bir sihirbazdın ki; beni bile kaybettin.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Saat 12'den sonra her içki şaraptır.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Seni bir kere öpsem ikinin hatırı kalıyordu iki kere öpeyim desem üçün boynu bükük...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Senin bir havan var beni asıl saran o. Onunla daha bir değere biniyor soluk almak.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Tek yanlı aşk kişiyi nasıl aptallaştırıyor, nasıl unutmuşum senin bir başkasını sevdiğini...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Yalnızlık bir ovanın düz oluşu gibi bir şey.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Rastlaşmamak için elimden geleni yaparım, bu böyle pek de kolay değil gerçi...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Birlikte mısralar düşünüyoruz ama iyi ama kötü; Boynun diyorum boynunu benim kadar kimse değerlendiremez.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "İkide bir elini başına götürüp rüzgârda dağılan yalnızlığını düzeltiyorsun.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Sizin hiç babanız öldü mü? Benim bir kere öldü kör oldum.. Yıkadılar aldılar götürdüler, babamdan ummazdım bunu kör oldum!", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "İki kişiyi birden severdim, karnemde sevinç bir aşk iki.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Garson şarap getir, garsonun hali harap.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Kim istemez ki mutlu olmayı, ama mutsuzluğa da var mısın?", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Ölüm mü, bir gölün dibinde durgun uykudasın. Denizler? Tanrılar karıştırır durur denizleri...", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Yürüyor muyduk, Yoksa bir doğa parçasının Altını mı çizdiriyorlardı bize?", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Okyanusta ölmez de insan, gider bir kaşık sevdada boğulur.", Author = "Cemal Süreya" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Cemal_Süreya", Text = "Biz hepimiz yeni kalmak istedik. Bizim için yenilik, öbür öğelerden baskın bir öğe oldu hep.", Author = "Cemal Süreya" },
